from functools import cache

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        if s == "":
            return False

        @cache
        def dp(i, j):
            if j == len(p):
                return i == len(s)

            if p[j] == "*":
                return (
                    dp(i, j + 1) or
                    (i < len(s) and dp(i + 1, j))
                )

            if i < len(s) and (s[i] == p[j] or p[j] == "?"):
                return dp(i + 1, j + 1)

            return False

        return dp(0, 0)